-- One shared account table. Allowed roles: reader, admin.
-- UUID is generated by the Backend; raw passwords/recovery codes are never stored.
CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY NOT NULL
        CHECK (
            length(id) = 36
            AND substr(id, 9, 1) = '-'
            AND substr(id, 14, 1) = '-'
            AND substr(id, 19, 1) = '-'
            AND substr(id, 24, 1) = '-'
            AND id = lower(id)
        ),

    password_hash TEXT NOT NULL,
    recovery_key_hash TEXT NOT NULL,

    role TEXT NOT NULL DEFAULT 'reader'
        CHECK (role IN ('reader', 'admin')),

    display_name TEXT NOT NULL,
    avatar_key TEXT,

    is_active INTEGER NOT NULL DEFAULT 1
        CHECK (is_active IN (0, 1)),

    created_at TEXT NOT NULL
        DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

    updated_at TEXT NOT NULL
        DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

    CHECK (length(trim(display_name)) BETWEEN 1 AND 100),
    CHECK (length(password_hash) >= 20),
    CHECK (length(recovery_key_hash) >= 20),
    CHECK (
        avatar_key IS NULL OR (
            length(avatar_key) = 24
            AND avatar_key = lower(avatar_key)
            AND avatar_key NOT GLOB '*[^0-9a-f]*'
        )
    )
);
